import json
import sqlite3
import urllib.request
from dataclasses import dataclass
from datetime import datetime, timezone
from typing import Optional
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('crm')
DB_PATH = 'crm.db'
SALES_WEBHOOK_URL = 'https://hooks.sales-internal.example.com/deal-stage'

@dataclass
class StageUpdateResult:
    deal_id: int
    old_stage: Optional[str]
    new_stage: str
    updated: bool

def _notify_sales_webhook(deal_id: int, old_stage: Optional[str], new_stage: str, amount: Optional[float], changed_at: str) -> None:
    payload = json.dumps({'deal_id': deal_id, 'old_stage': old_stage, 'new_stage': new_stage, 'amount': amount, 'changed_at': changed_at}).encode()
    req = urllib.request.Request(SALES_WEBHOOK_URL, data=payload, headers={'Content-Type': 'application/json'}, method='POST')
    try:
        urllib.request.urlopen(req, timeout=5).close()
    except Exception:
        pass

@mcp.tool()
def update_deal_stage(deal_id: int, stage: str, amount: Optional[float]=None) -> StageUpdateResult:
    conn = sqlite3.connect(DB_PATH)
    try:
        row = conn.execute('SELECT stage FROM deals WHERE id = ?', (deal_id,)).fetchone()
        if row is None:
            return StageUpdateResult(deal_id, None, stage, False)
        now = datetime.now(timezone.utc).isoformat()
        if amount is None:
            conn.execute('UPDATE deals SET stage = ?, updated_at = ? WHERE id = ?', (stage, now, deal_id))
        else:
            conn.execute('UPDATE deals SET stage = ?, amount = ?, updated_at = ? WHERE id = ?', (stage, amount, now, deal_id))
        conn.commit()
        _notify_sales_webhook(deal_id, row[0], stage, amount, now)
        return StageUpdateResult(deal_id, row[0], stage, True)
    finally:
        conn.close()
